import{_ as a,C as s,o as r,c as n,aj as o,E as d}from"./framework.js";const _=JSON.parse('{"title":"基础 · 访问控制 Tab | Cms / Settings / Basic | Documentation","description":"基础 · 访问控制 Tab in Kooboo: 控制 谁可以访问站点哪些路径：站点类型（公开/会员/私有）、路径白名单或黑名单、单点登录、地区限制、请求限流与封禁、CORS，以及云端 开发密码 预览模式。","frontmatter":{"title":"基础 · 访问控制 Tab | Cms / Settings / Basic | Documentation","description":"基础 · 访问控制 Tab in Kooboo: 控制 谁可以访问站点哪些路径：站点类型（公开/会员/私有）、路径白名单或黑名单、单点登录、地区限制、请求限流与封禁、CORS，以及云端 开发密码 预览模式。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/basic/access.html"}]]},"headers":[],"relativePath":"zh/cms/settings/basic/access.md","filePath":"cms/settings/basic/access.md","lastUpdated":1780899944000}'),c={name:"zh/cms/settings/basic/access.md"};function i(h,t,g,l,b,p){const e=s("DocImage");return r(),n("div",null,[t[0]||(t[0]=o('<h1 id="基础-·-访问控制-tab" tabindex="-1">基础 · 访问控制 Tab <a class="header-anchor" href="#基础-·-访问控制-tab" aria-label="Permalink to &quot;基础 · 访问控制 Tab&quot;">​</a></h1><blockquote><p>Tab：<strong>访问控制</strong> · <code>name=access</code><br> 深链：<code>/_Admin/system/settings?SiteId={站点GUID}&amp;name=access</code></p></blockquote><p>控制 <strong>谁可以访问站点哪些路径</strong>：站点类型（公开/会员/私有）、路径白名单或黑名单、单点登录、地区限制、请求限流与封禁、CORS，以及云端 <strong>开发密码</strong> 预览模式。</p>',3)),d(e,{src:"/cms/settings/settings-basic-access.png",alt:"访问控制 Tab",width:"1120"}),t[1]||(t[1]=o('<h2 id="站点类型" tabindex="-1">站点类型 <a class="header-anchor" href="#站点类型" aria-label="Permalink to &quot;站点类型&quot;">​</a></h2><p><strong>站点类型</strong> 下拉（<code>siteType</code>）决定未匹配特殊路径时的默认访问策略，常见取值包括 <strong>公开</strong>（<code>p</code>）、<strong>会员</strong>（<code>m</code>）、<strong>私有</strong>（<code>o</code>）等（以接口 <code>getTypes</code> 返回为准）。</p><p>当类型 <strong>不是公开</strong> 时，下方出现 <strong>路径模式</strong> 区域：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>路径模式</strong></td><td><strong>包含路径</strong>（仅列出的路径可访问）或 <strong>排除路径</strong>（列出路径禁止，其余可访问）</td></tr><tr><td><strong>路径列表</strong></td><td>多条路径模式字符串，可 <strong>添加</strong> / <strong>删除</strong> 行</td></tr><tr><td><strong>单点登录</strong></td><td><code>ssoLogin</code>：与 SSO 集成配合（须已在 <a href="./../integrations/">服务集成</a> 配置）</td></tr></tbody></table><h2 id="访客国家-地区限制" tabindex="-1">访客国家/地区限制 <a class="header-anchor" href="#访客国家-地区限制" aria-label="Permalink to &quot;访客国家/地区限制&quot;">​</a></h2><p>在 <strong>Kooboo 在线服务器</strong> 环境显示（<code>isOnlineServer</code>）。开启后可勾选禁止访问的国家/地区，并指定受限访客跳转的 <strong>页面</strong>。</p><h2 id="ip-请求速率限制" tabindex="-1">IP 请求速率限制 <a class="header-anchor" href="#ip-请求速率限制" aria-label="Permalink to &quot;IP 请求速率限制&quot;">​</a></h2><p>分组 <strong>IP 请求速率限制</strong>（<code>rateLimitSettings</code>）：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>限制全部请求</strong></td><td>开启后对全站统一限速；关闭后可按 <strong>IP</strong>、<strong>User-Agent</strong> 分别配置 <code>withinSeconds</code> / <code>permitLimit</code></td></tr><tr><td>IP / UA 规则</td><td>多行键值编辑，键为 IP 或 UA 字符串</td></tr></tbody></table><h2 id="请求封禁" tabindex="-1">请求封禁 <a class="header-anchor" href="#请求封禁" aria-label="Permalink to &quot;请求封禁&quot;">​</a></h2><p>分组 <strong>请求封禁</strong>（<code>accessLimitSettings</code>）：</p><table tabindex="0"><thead><tr><th>列表</th><th>说明</th></tr></thead><tbody><tr><td><strong>IP 黑名单</strong></td><td>命中 IP 直接拒绝</td></tr><tr><td><strong>User-Agent 黑名单</strong></td><td>关键词匹配 UA 拒绝</td></tr></tbody></table><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p><strong>CORS</strong> 开关（<code>enableCORS</code>）：允许跨域访问站点 API/资源时的浏览器 CORS 响应（详见界面 Tooltip）。</p><h2 id="开发密码-在线公有云" tabindex="-1">开发密码（在线公有云） <a class="header-anchor" href="#开发密码-在线公有云" aria-label="Permalink to &quot;开发密码（在线公有云）&quot;">​</a></h2><p>在 <strong>在线服务器且非私有部署</strong> 且服务等级满足时显示：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用开发密码</strong></td><td>将站点状态在 <code>Published</code> / <code>Development</code> 间切换</td></tr><tr><td><strong>开发密码</strong></td><td><code>Development</code> 状态下展示只读密码，访客须输入方可预览站点</td></tr></tbody></table><p>私有部署或本地环境可能不显示此区块。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./">基础设置概述</a></li><li><a href="./../../operations/visitor-logs.html">运维 · 访问日志</a>（观测流量，非本 Tab 限流）</li><li><a href="./../request-hooks.html">请求 Hook</a>（脚本级拦截）</li></ul>',20))])}const u=a(c,[["render",i]]);export{_ as __pageData,u as default};
